ENTITY aluDecoder IS
    GENERIC( 
        g_tDec : time := 25 ps
    );
    PORT( 
        ALUOp      : IN     std_ulogic_vector (1 DOWNTO 0);
        funct3     : IN     std_ulogic_vector (2 DOWNTO 0);
        funct7     : IN     std_ulogic;
        op         : IN     std_ulogic;
        ALUControl : OUT    std_ulogic_vector (2 DOWNTO 0)
    );

