--
-- VHDL Architecture HEIRV32_MC.mainFSM.studentVersion
--
-- Created:
--          by - allan.brunner.UNKNOWN (VS-W11669)
--          at - 11:08:49 26.05.2026
--
-- Generated by Mentor Graphics' HDL Designer(TM) 2019.2 (Build 5)
--
LIBRARY ieee;
  USE ieee.std_logic_1164.all;
  USE ieee.numeric_std.all;
LIBRARY gates;
USE gates.gates.all;
 
ARCHITECTURE studentVersion OF mainFSM IS

    TYPE STATE_TYPE IS (
        Fetch,
        Decode,
        MemAddr,
        MemRead,
        MemWriteBack,
        memoryWrite,
        ALUWriteBack,
        ExecuteR,
        ExecuteI,
        JAL,
        BEQ,
        JALR
    );
 
    -- Declare current and next state signals
    SIGNAL current_state : STATE_TYPE;
    SIGNAL next_state : STATE_TYPE;

BEGIN

    -----------------------------------------------------------------
    clocked_proc : PROCESS ( 
        clk,
        rst
    )
    -----------------------------------------------------------------
    BEGIN
        IF (rst = '1') THEN
            current_state <= Fetch;
        ELSIF (clk'EVENT AND clk = '1') THEN
            IF (en = '1') THEN
                current_state <= next_state;
            END IF;
        END IF;
    END PROCESS clocked_proc;
 
    -----------------------------------------------------------------
    nextstate_proc : PROCESS ( 
        current_state,
        op
    )
    -----------------------------------------------------------------
    BEGIN
        CASE current_state IS
            WHEN Fetch => 
                next_state <= Decode;
            WHEN Decode => 
                IF (op = "0000011" OR 
                    op = "0100011") THEN 
                    next_state <= MemAddr;
                ELSIF (op = "1101111") THEN 
                    next_state <= JAL;
                ELSIF (op = "0010011") THEN 
                    next_state <= ExecuteI;
                ELSIF (op = "0110011") THEN 
                    next_state <= ExecuteR;
                ELSIF (op = "1100011") THEN 
                    next_state <= BEQ;
                ELSIF (op = "1100111") THEN 
                    next_state <= JALR;
                ELSE
                    next_state <= Decode;
                END IF;
            WHEN MemAddr => 
                IF (op = "0000011") THEN 
                    next_state <= MemRead;
                ELSIF (op = "0100011") THEN 
                    next_state <= memoryWrite;
                ELSE
                    next_state <= MemAddr;
                END IF;
            WHEN MemRead => 
                next_state <= MemWriteBack;
            WHEN MemWriteBack => 
                next_state <= Fetch;
            WHEN memoryWrite => 
                next_state <= Fetch;
            WHEN ALUWriteBack => 
                next_state <= Fetch;
            WHEN ExecuteR => 
                next_state <= ALUWriteBack;
            WHEN ExecuteI => 
                next_state <= ALUWriteBack;
            WHEN JAL => 
                next_state <= ALUWriteBack;
            WHEN BEQ => 
                next_state <= Fetch;
            WHEN JALR => 
                next_state <= JAL;
            WHEN OTHERS =>
                next_state <= Fetch;
        END CASE;
    END PROCESS nextstate_proc;
 
    -----------------------------------------------------------------
    output_proc : PROCESS ( 
        current_state
    )
    -----------------------------------------------------------------
    BEGIN
        -- Default Assignment
        ALUOp <= (others => '0');
        ALUSrcA <= (others => '0');
        ALUSrcB <= (others => '0');
        IRWrite <= '0';
        PCupdate <= '0';
        adrSrc <= '0';
        branch <= '0';
        memWrite <= '0';
        regwrite <= '0';
        resultSrc <= (others => '0');

        -- Combined Actions
        CASE current_state IS
            WHEN Fetch => 
                AdrSrc <= '0';
                IRWrite <= '1';
                resultSrc <= "10";
                ALUSrcA <= "00";
                ALUSrcB <= "10";
                ALUOp <= "00";
                PCupdate <= '1';
            WHEN Decode => 
                ALUSrcA <= "01";
                ALUSrcB <= "01";
                ALUOp <= "00";
            WHEN MemAddr => 
                ALUSrcA <= "10";
                ALUSrcB <= "01";
                ALUOp <= "00";
            WHEN MemRead => 
                ResultSrc <= "00";
                AdrSrc <= '1';
            WHEN MemWriteBack => 
                ResultSrc <="01";
                RegWrite <= '1';
            WHEN memoryWrite => 
                ResultSrc <= "00";
                AdrSrc <= '1';
                MemWrite <= '1';
            WHEN ALUWriteBack => 
                ResultSrc <= "00";
                RegWrite <= '1';
            WHEN ExecuteR => 
                ALUSrcA <= "10";
                ALUSrcB <= "00";
                ALUOp <= "10";
            WHEN ExecuteI => 
                ALUSrcA <= "10";
                ALUSrcB <= "01";
                ALUOp <= "10";
            WHEN JAL => 
                ALUSrcA <= "01";
                ALUSrcB <= "10";
                ALUOp <= "00";
                ResultSrc <= "00";
                PCUpdate <= '1';
            WHEN BEQ => 
                ALUSrcA <= "10";
                ALUSrcB <= "00";
                ALUOp <= "01";
                ResultSrc <= "00";
                branch <= '1';
                PCUpdate <= '0';
            WHEN JALR => 
                ALUSrcA <= "10";
                ALUSrcB <= "01";
                ALUOp <= "00";
            WHEN OTHERS =>
                NULL;
        END CASE;
    END PROCESS output_proc;
 
END studentVersion;




