LIBRARY ieee;
  USE ieee.std_logic_1164.all;
  USE ieee.numeric_std.all;
LIBRARY gates;
  USE gates.gates.all;

ENTITY mux2to1ULogicVector IS
    GENERIC( 
        dataBitNb : positive := 8;
        delay     : time     := gateDelay
    );
    PORT( 
        in0    : IN     std_uLogic_vector (dataBitNb-1 DOWNTO 0);
        in1    : IN     std_uLogic_vector (dataBitNb-1 DOWNTO 0);
        sel    : IN     std_uLogic;
        muxOut : OUT    std_uLogic_vector (dataBitNb-1 DOWNTO 0)
    );

-- Declarations

END mux2to1ULogicVector ;





ARCHITECTURE sim OF mux2to1ULogicVector IS

  signal selInt: std_ulogic;

BEGIN

  selInt <= to_X01(sel);

  muxSelect: process(selInt, in0, in1)
  begin
    if selInt = '0' then
      muxOut <= in0 after delay;
    elsif selInt = '1' then
      muxOut <= in1 after delay;
    elsif in0 = in1 then
      muxOut <= in0 after delay;
    else
      muxOut <= (others => 'X') after delay;
    end if;
  end process muxSelect;

END ARCHITECTURE sim;




